const flashcards=[{"id": "cte-marco-1", "block": "marco", "page": 3, "q": "¿Qué sección facilita la intervención de rescate y extinción?", "a": "<b>SI 5</b>. SI 5 trata de la intervención de los bomberos; SI 3, de evacuación; SI 6, de resistencia estructural."}, {"id": "cte-marco-2", "block": "marco", "page": 5, "q": "Un centro sanitario exclusivamente ambulatorio sigue las condiciones de uso…", "a": "<b>Administrativo</b>. La introducción distingue la asistencia ambulatoria de los usos con ocupantes que necesitan ayuda para evacuar."}, {"id": "cte-marco-3", "block": "marco", "page": 7, "q": "En productos sin marcado CE, los informes de ensayo de reacción y resistencia deben tener, respectivamente, antigüedad…", "a": "<b>Menor que 5 y menor que 10 años</b>. La fecha de referencia es el suministro a la obra. Reacción y resistencia tienen plazos diferentes."}, {"id": "cte-terminos-1", "block": "terminos", "page": 46, "q": "La contribución de un material al desarrollo del incendio define su…", "a": "<b>Reacción al fuego</b>. La reacción se refiere a la contribución del material por su propia combustión. La resistencia se refiere a funciones mantenidas por un elemento durante un tiempo."}, {"id": "cte-terminos-2", "block": "terminos", "page": 48, "q": "Dos recorridos pueden ser alternativos si forman un ángulo…", "a": "<b>Mayor que 45°</b>. La otra opción es separarlos mediante elementos EI 30 que eviten el bloqueo simultáneo por humo."}, {"id": "cte-terminos-3", "block": "terminos", "page": 45, "q": "Para P > 50, la comprobación geométrica de dispersión del espacio exterior seguro utiliza…", "a": "<b>0,5P m² dentro de un radio 0,1P m</b>. Esta comprobación se suma a las demás condiciones del espacio exterior seguro. Con P ≤ 50 no es necesario comprobar esa condición concreta."}, {"id": "cte-sectores-1", "block": "sectores", "page": 11, "q": "En Docente con más de una planta, la superficie máxima base por sector es…", "a": "<b>4.000 m²</b>. La tabla diferencia los edificios docentes de una sola planta, donde no exige compartimentación en sectores."}, {"id": "cte-sectores-2", "block": "sectores", "page": 12, "q": "En un aparcamiento robotizado bajo otro uso, el límite por sector es…", "a": "<b>10.000 m³</b>. La unidad es volumen construido, no superficie."}, {"id": "cte-sectores-3", "block": "sectores", "page": 12, "q": "Como regla, una planta con hospitalización se divide en…", "a": "<b>Al menos dos sectores, cada uno de hasta 1.500 m²</b>. Cada sector debe poder albergar a los pacientes de un sector contiguo. Existe la excepción para planta ≤ 1.500 m² con salidas directas a exterior seguro y recorridos ≤ 25 m."}, {"id": "cte-resistencia-sector-1", "block": "resistencia-sector", "page": 13, "q": "Una puerta directa entre sectores en una pared EI 120 será, por la regla general…", "a": "<b>EI₂ 60-C5</b>. El tiempo de la puerta directa es la mitad del requerido a la pared."}, {"id": "cte-resistencia-sector-2", "block": "resistencia-sector", "page": 13, "q": "Con vestíbulo y dos puertas en una separación EI 120, cada puerta puede ser…", "a": "<b>EI₂ 30-C5</b>. La cuarta parte se aplica cuando el paso se realiza mediante vestíbulo de independencia y dos puertas."}, {"id": "cte-resistencia-sector-3", "block": "resistencia-sector", "page": 13, "q": "Un techo portante que separa el sector de una planta superior debe aportar…", "a": "<b>REI, con el tiempo exigible a la separación</b>. Además de separar y aislar, el elemento tiene función portante; por eso la clasificación pasa de EI a REI."}, {"id": "cte-riesgo-1", "block": "riesgo", "page": 16, "q": "Las puertas de una zona de riesgo especial medio son…", "a": "<b>Dos EI₂ 30-C5 con vestíbulo</b>. El riesgo alto exige dos EI₂ 45-C5. El medio exige dos EI₂ 30-C5 y vestíbulo."}, {"id": "cte-riesgo-2", "block": "riesgo", "page": 14, "q": "Según la fila de potencia, una cocina de exactamente 50 kW se clasifica como…", "a": "<b>Riesgo medio</b>. El tramo medio es 30 &lt; P ≤ 50; el alto comienza por encima de 50. Se aplican además las excepciones de la nota 2."}, {"id": "cte-riesgo-3", "block": "riesgo", "page": 16, "q": "El recorrido máximo base hasta alguna salida del local de riesgo especial es…", "a": "<b>25 m</b>. Puede aumentarse un 25% con extinción automática. No confundas este recorrido de evacuación con los 10 o 15 m hasta extintores de SI 4."}, {"id": "cte-reaccion-1", "block": "reaccion", "page": 16, "q": "La exclusión por sección de paso de una penetración llega hasta…", "a": "<b>50 cm² inclusive</b>. SI 1-3 excluye las penetraciones cuya sección no excede de 50 cm²."}, {"id": "cte-reaccion-2", "block": "reaccion", "page": 17, "q": "El revestimiento de suelo de un pasillo protegido será, según tabla 4.1…", "a": "<b>C_FL-s1</b>. C_FL-s1 corresponde a suelos de pasillos y escaleras protegidos; B-s1,d0 a sus paredes y techos."}, {"id": "cte-reaccion-3", "block": "reaccion", "page": 17, "q": "El porcentaje que activa las condiciones de revestimientos de la tabla 4.1 es…", "a": "<b>Más del 5% de la superficie del conjunto correspondiente</b>. Se comprueba por separado el conjunto de paredes, el de techos o el de suelos del recinto."}, {"id": "cte-exterior-1", "block": "exterior", "page": 19, "q": "La separación mínima de puntos no EI 60 en fachadas a 90° es…", "a": "<b>2 m</b>. La tabla SI 2-1 relaciona ángulo y distancia: a 90°, 2 m; a 0°, 3 m; a 180°, 0,50 m."}, {"id": "cte-exterior-2", "block": "exterior", "page": 20, "q": "La franja base para limitar propagación vertical por fachada es…", "a": "<b>EI 60 y 1 m de altura</b>. Su altura puede reducirse en la dimensión de un saliente apto para impedir el paso de las llamas."}, {"id": "cte-exterior-3", "block": "exterior", "page": 20, "q": "En una cámara ventilada de fachada de más de 28 m, el aislamiento será al menos…", "a": "<b>A2-s3,d0</b>. No confundas la clasificación del aislamiento de la cámara con la del sistema constructivo de fachada."}, {"id": "cte-ocupacion-1", "block": "ocupacion", "page": 23, "q": "La densidad para plantas de vivienda es…", "a": "<b>20 m²/persona</b>. La tabla usa superficie útil por persona. Las zonas de alojamiento residencial público también tienen 20 m²/persona."}, {"id": "cte-ocupacion-2", "block": "ocupacion", "page": 23, "q": "Un aula ordinaria de 90 m² útiles, con la densidad de tabla y sin otras condiciones, tiene…", "a": "<b>60 ocupantes</b>. Se divide la superficie útil entre 1,5 m²/persona."}, {"id": "cte-ocupacion-3", "block": "ocupacion", "page": 23, "q": "0,25 m²/persona para espectadores de pie equivale a…", "a": "<b>4 personas/m²</b>. La densidad está expresada en superficie por persona; para invertirla, 1 / 0,25 = 4."}, {"id": "cte-salidas-1", "block": "salidas", "page": 25, "q": "Con una única salida, el recorrido máximo específico en Aparcamiento es…", "a": "<b>35 m</b>. La regla general de una salida es 25 m; Aparcamiento tiene 35 m. Hay además el supuesto de salida directa a exterior seguro y ≤ 25 personas."}, {"id": "cte-salidas-2", "block": "salidas", "page": 25, "q": "Con varias salidas, el recorrido máximo en zonas donde se prevé que duerman ocupantes es…", "a": "<b>35 m</b>. Los 15 m son el tramo hasta alternativas en plantas de hospitalización/tratamiento intensivo, no el recorrido total de todas las zonas donde se duerme."}, {"id": "cte-salidas-3", "block": "salidas", "page": 25, "q": "La extinción automática permite aumentar las longitudes de la tabla 3.1 en…", "a": "<b>25%</b>. La nota 1 se refiere a sectores protegidos con instalación automática de extinción. No duplica automáticamente las longitudes."}, {"id": "cte-anchuras-1", "block": "anchuras", "page": 26, "q": "Para P = 240 asignadas a una puerta, P/200 da…", "a": "<b>1,20 m</b>. El mínimo de 0,80 m no sustituye a la anchura que resulte del número de personas."}, {"id": "cte-anchuras-2", "block": "anchuras", "page": 26, "q": "La fórmula de una escalera no protegida para evacuación ascendente es…", "a": "<b>A ≥ P/(160 − 10h)</b>. El término de altura h reduce la capacidad de la escalera ascendente."}, {"id": "cte-anchuras-3", "block": "anchuras", "page": 25, "q": "Si deben existir varias escaleras protegidas, el cálculo…", "a": "<b>No exige inutilizar completamente una de ellas</b>. La excepción al bloqueo total se aplica a protegidas, especialmente protegidas y compartimentadas como sector; no elimina el resto de hipótesis de asignación."}, {"id": "cte-escaleras-1", "block": "escaleras", "page": 28, "q": "Una escalera descendente de vivienda con h = 18 m exige como mínimo…", "a": "<b>Protegida</b>. La no protegida llega hasta 14 m; la protegida se admite hasta 28 m."}, {"id": "cte-escaleras-2", "block": "escaleras", "page": 28, "q": "En Aparcamiento, las escaleras de evacuación deben ser…", "a": "<b>Especialmente protegidas</b>. La tabla no admite las dos categorías inferiores en Aparcamiento, tanto para evacuación descendente como ascendente."}, {"id": "cte-escaleras-3", "block": "escaleras", "page": 45, "q": "La opción de ventilación natural de una escalera protegida exige, por planta…", "a": "<b>Al menos 1 m² útil de ventilación</b>. Es una de las tres opciones de protección frente al humo; no es la definición de escalera abierta al exterior."}, {"id": "cte-puertas-1", "block": "puertas", "page": 29, "q": "Una puerta de salida de un recinto con 60 ocupantes debe abrir…", "a": "<b>En el sentido de evacuación</b>. El criterio de más de 50 ocupantes del recinto es independiente del de 100 o 200 personas por puerta."}, {"id": "cte-puertas-2", "block": "puertas", "page": 29, "q": "Para usuarios no familiarizados, la barra horizontal de apertura se asocia a…", "a": "<b>UNE-EN 1125</b>. UNE-EN 179 corresponde a manilla o pulsador para usuarios familiarizados. La señalización se regula en UNE 23034."}, {"id": "cte-puertas-3", "block": "puertas", "page": 30, "q": "La señal «Sin salida» se coloca…", "a": "<b>Junto a la puerta, nunca sobre sus hojas</b>. Debe ser fácilmente visible sin colocarse sobre las hojas de la puerta."}, {"id": "cte-humo-refugio-1", "block": "humo-refugio", "page": 31, "q": "Para 220 ocupantes, cuando procede refugio en uso distinto de vivienda, la dotación es…", "a": "<b>3 plazas de silla y 7 de otra movilidad reducida</b>. Se aplica una plaza por cada 100 y por cada 33 ocupantes o fracción. La excepción de la segunda dotación corresponde a vivienda."}, {"id": "cte-humo-refugio-2", "block": "humo-refugio", "page": 30, "q": "En Comercial o Pública concurrencia, SI 3 exige control de humo por ocupación cuando esta…", "a": "<b>Excede de 1.000 personas</b>. El umbral de 500 se refiere a los atrios en los términos del apartado, no a estos dos usos en general."}, {"id": "cte-humo-refugio-3", "block": "humo-refugio", "page": 30, "q": "La solución mecánica de aparcamiento de SI 3 indica extracción y aportación máxima de…", "a": "<b>150 y 120 l/(plaza·s), respectivamente</b>. No intercambies los valores ni cambies litros por metros cúbicos. Se requiere activación automática por detección."}, {"id": "cte-instalaciones-1", "block": "instalaciones", "page": 32, "q": "La referencia general de eficacia y recorrido hasta extintor es…", "a": "<b>21A-113B y máximo 15 m</b>. Se mide recorrido desde todo origen de evacuación, en cada planta."}, {"id": "cte-instalaciones-2", "block": "instalaciones", "page": 33, "q": "En una cocina de uso Hospitalario, la extinción automática se exige si la potencia…", "a": "<b>Excede de 20 kW</b>. El umbral para Hospitalario y Residencial Público es mayor que 20 kW; para los demás usos, mayor que 50 kW."}, {"id": "cte-instalaciones-3", "block": "instalaciones", "page": 35, "q": "En riesgo especial alto, el recorrido real hasta algún extintor no será mayor que…", "a": "<b>10 m</b>. Se cuenta también el extintor exterior próximo a la puerta. Los 25 m de SI 1 se refieren a evacuación hasta alguna salida del local."}, {"id": "cte-dotacion-usos-1", "block": "dotacion-usos", "page": 33, "q": "La columna seca se exige en Hospitalario si la altura de evacuación…", "a": "<b>Excede de 15 m</b>. El umbral hospitalario es distinto al de vivienda y varios de los demás usos."}, {"id": "cte-dotacion-usos-2", "block": "dotacion-usos", "page": 34, "q": "En Pública concurrencia, el sistema de alarma con megafonía se exige si…", "a": "<b>La ocupación excede de 500 personas</b>. No confundas el umbral de ocupación de alarma con el de superficie para BIE."}, {"id": "cte-dotacion-usos-3", "block": "dotacion-usos", "page": 35, "q": "Un aparcamiento robotizado debe disponer en todo caso de…", "a": "<b>Pulsadores de alarma y extinción automática</b>. La tabla impone estos dos sistemas sin umbral de superficie para el robotizado."}, {"id": "cte-aproximacion-1", "block": "aproximacion", "page": 36, "q": "El vial de aproximación debe tener anchura y gálibo mínimos de…", "a": "<b>3,5 y 4,5 m</b>. La anchura de 5 m pertenece al espacio de maniobra, no al vial."}, {"id": "cte-aproximacion-2", "block": "aproximacion", "page": 36, "q": "La capacidad portante del vial de aproximación es…", "a": "<b>20 kN/m²</b>. Es una carga por superficie. El requisito de punzonamiento del espacio de maniobra usa otra magnitud."}, {"id": "cte-aproximacion-3", "block": "aproximacion", "page": 36, "q": "En curva, los radios mínimos interior y exterior son…", "a": "<b>5,30 y 12,50 m</b>. La anchura libre de circulación correspondiente es 7,20 m."}, {"id": "cte-maniobra-1", "block": "maniobra", "page": 36, "q": "Para altura de evacuación de 18 m, la separación máxima a fachada es…", "a": "<b>18 m</b>. 18 m pertenece al tramo mayor de 15 y hasta 20 m de altura de evacuación."}, {"id": "cte-maniobra-2", "block": "maniobra", "page": 36, "q": "El espacio de maniobra se exige por el apartado 1.2 con altura descendente…", "a": "<b>Mayor que 9 m</b>. No confundas la altura que activa el requisito con los tramos que fijan la separación a fachada."}, {"id": "cte-maniobra-3", "block": "maniobra", "page": 37, "q": "La distancia del equipo de bombeo a cada conexión de columna seca debe ser…", "a": "<b>Menor que 18 m</b>. Además, el punto de conexión debe ser visible desde el camión de bombeo. Los 30 m se refieren al acceso al edificio."}, {"id": "cte-fachada-forestal-1", "block": "fachada-forestal", "page": 37, "q": "Las dimensiones mínimas horizontal y vertical del hueco de acceso son…", "a": "<b>0,80 × 1,20 m</b>. Además, alféizar ≤ 1,20 m y separación entre ejes consecutivos ≤ 25 m."}, {"id": "cte-fachada-forestal-2", "block": "fachada-forestal", "page": 37, "q": "El camino perimetral de 5 m en entorno forestal…", "a": "<b>Puede estar incluido en la franja de 25 m</b>. La franja y el camino son requisitos relacionados; el texto permite incluir el camino en la franja."}, {"id": "cte-fachada-forestal-3", "block": "fachada-forestal", "page": 37, "q": "Si no hay dos vías de acceso alternativas en la zona forestal, el acceso único acaba en…", "a": "<b>Fondo de saco circular de radio 12,50 m</b>. 12,50 m es el radio, no el diámetro. También se mantienen las condiciones de espacio sin obstáculos."}, {"id": "cte-estructura-1", "block": "estructura", "page": 39, "q": "La estructura de un aparcamiento situado bajo otro uso exige como regla…", "a": "<b>R 120</b>. Si el aparcamiento es robotizado bajo otro uso, R 180. El exclusivo o situado sobre otro uso tiene R 90."}, {"id": "cte-estructura-2", "block": "estructura", "page": 39, "q": "En Administrativo sobre rasante, con altura de evacuación de 20 m, la tabla exige…", "a": "<b>R 90</b>. El tramo es mayor de 15 y hasta 28 m. No uses la fila de Comercial/Hospitalario."}, {"id": "cte-estructura-3", "block": "estructura", "page": 39, "q": "SI 6 considera la capacidad portante de la estructura tras el incendio…", "a": "<b>No, queda fuera de su evaluación</b>. SI 6 evalúa la resistencia durante el incendio; no acredita la capacidad portante residual."}, {"id": "cte-anejos-1", "block": "anejos", "page": 53, "q": "En la curva θg = 20 + 345 log₁₀(8t + 1), t se mide en…", "a": "<b>Minutos</b>. La temperatura se expresa en grados Celsius y t es el tiempo desde el inicio en minutos."}, {"id": "cte-anejos-2", "block": "anejos", "page": 73, "q": "El método de la sección reducida corresponde al anejo de…", "a": "<b>Madera, Anejo E</b>. La sección eficaz se obtiene eliminando la profundidad de carbonización eficaz en las caras expuestas."}, {"id": "cte-anejos-3", "block": "anejos", "page": 85, "q": "Para tablas de resistencia de muros de ladrillo y bloques de hormigón consultarías…", "a": "<b>Anejo F</b>. El Anejo F trata de elementos de fábrica; B, del tiempo equivalente; D, del acero."}];
const quizdata=[{"id": "cte-q1", "block": "marco", "page": 3, "q": "¿Qué sección facilita la intervención de rescate y extinción?", "options": ["SI 5", "SI 3", "SI 6"], "correct": 0, "explanation": "SI 5 trata de la intervención de los bomberos; SI 3, de evacuación; SI 6, de resistencia estructural."}, {"id": "cte-q2", "block": "marco", "page": 5, "q": "Un centro sanitario exclusivamente ambulatorio sigue las condiciones de uso…", "options": ["Hospitalario en todo caso", "Administrativo", "Residencial Público"], "correct": 1, "explanation": "La introducción distingue la asistencia ambulatoria de los usos con ocupantes que necesitan ayuda para evacuar."}, {"id": "cte-q3", "block": "marco", "page": 7, "q": "En productos sin marcado CE, los informes de ensayo de reacción y resistencia deben tener, respectivamente, antigüedad…", "options": ["Menor que 10 y menor que 5 años", "Menor que 5 años en ambos casos", "Menor que 5 y menor que 10 años"], "correct": 2, "explanation": "La fecha de referencia es el suministro a la obra. Reacción y resistencia tienen plazos diferentes."}, {"id": "cte-q4", "block": "terminos", "page": 46, "q": "La contribución de un material al desarrollo del incendio define su…", "options": ["Reacción al fuego", "Resistencia al fuego", "Altura de evacuación"], "correct": 0, "explanation": "La reacción se refiere a la contribución del material por su propia combustión. La resistencia se refiere a funciones mantenidas por un elemento durante un tiempo."}, {"id": "cte-q5", "block": "terminos", "page": 48, "q": "Dos recorridos pueden ser alternativos si forman un ángulo…", "options": ["Igual a 45° en todos los casos", "Mayor que 45°", "Mayor que 15°"], "correct": 1, "explanation": "La otra opción es separarlos mediante elementos EI 30 que eviten el bloqueo simultáneo por humo."}, {"id": "cte-q6", "block": "terminos", "page": 45, "q": "Para P > 50, la comprobación geométrica de dispersión del espacio exterior seguro utiliza…", "options": ["0,1P m² dentro de un radio 0,5P m", "1 m² por persona sin condición de radio", "0,5P m² dentro de un radio 0,1P m"], "correct": 2, "explanation": "Esta comprobación se suma a las demás condiciones del espacio exterior seguro. Con P ≤ 50 no es necesario comprobar esa condición concreta."}, {"id": "cte-q7", "block": "sectores", "page": 11, "q": "En Docente con más de una planta, la superficie máxima base por sector es…", "options": ["4.000 m²", "2.500 m²", "1.500 m²"], "correct": 0, "explanation": "La tabla diferencia los edificios docentes de una sola planta, donde no exige compartimentación en sectores."}, {"id": "cte-q8", "block": "sectores", "page": 12, "q": "En un aparcamiento robotizado bajo otro uso, el límite por sector es…", "options": ["10.000 m²", "10.000 m³", "2.500 m³"], "correct": 1, "explanation": "La unidad es volumen construido, no superficie."}, {"id": "cte-q9", "block": "sectores", "page": 12, "q": "Como regla, una planta con hospitalización se divide en…", "options": ["Un sector de 4.000 m²", "Dos sectores de hasta 5.000 m² cada uno", "Al menos dos sectores, cada uno de hasta 1.500 m²"], "correct": 2, "explanation": "Cada sector debe poder albergar a los pacientes de un sector contiguo. Existe la excepción para planta ≤ 1.500 m² con salidas directas a exterior seguro y recorridos ≤ 25 m."}, {"id": "cte-q10", "block": "resistencia-sector", "page": 13, "q": "Una puerta directa entre sectores en una pared EI 120 será, por la regla general…", "options": ["EI₂ 60-C5", "EI₂ 30-C5", "R 120"], "correct": 0, "explanation": "El tiempo de la puerta directa es la mitad del requerido a la pared."}, {"id": "cte-q11", "block": "resistencia-sector", "page": 13, "q": "Con vestíbulo y dos puertas en una separación EI 120, cada puerta puede ser…", "options": ["EI₂ 15-C5", "EI₂ 30-C5", "EI₂ 120-C5 obligatoriamente"], "correct": 1, "explanation": "La cuarta parte se aplica cuando el paso se realiza mediante vestíbulo de independencia y dos puertas."}, {"id": "cte-q12", "block": "resistencia-sector", "page": 13, "q": "Un techo portante que separa el sector de una planta superior debe aportar…", "options": ["Solo E", "Solo reacción al fuego clase B", "REI, con el tiempo exigible a la separación"], "correct": 2, "explanation": "Además de separar y aislar, el elemento tiene función portante; por eso la clasificación pasa de EI a REI."}, {"id": "cte-q13", "block": "riesgo", "page": 16, "q": "Las puertas de una zona de riesgo especial medio son…", "options": ["Dos EI₂ 30-C5 con vestíbulo", "Una EI₂ 30-C5 sin vestíbulo", "Dos EI₂ 45-C5 obligatoriamente"], "correct": 0, "explanation": "El riesgo alto exige dos EI₂ 45-C5. El medio exige dos EI₂ 30-C5 y vestíbulo."}, {"id": "cte-q14", "block": "riesgo", "page": 14, "q": "Según la fila de potencia, una cocina de exactamente 50 kW se clasifica como…", "options": ["Riesgo bajo", "Riesgo medio", "Riesgo alto"], "correct": 1, "explanation": "El tramo medio es 30 < P ≤ 50; el alto comienza por encima de 50. Se aplican además las excepciones de la nota 2."}, {"id": "cte-q15", "block": "riesgo", "page": 16, "q": "El recorrido máximo base hasta alguna salida del local de riesgo especial es…", "options": ["10 m", "50 m", "25 m"], "correct": 2, "explanation": "Puede aumentarse un 25% con extinción automática. No confundas este recorrido de evacuación con los 10 o 15 m hasta extintores de SI 4."}, {"id": "cte-q16", "block": "reaccion", "page": 16, "q": "La exclusión por sección de paso de una penetración llega hasta…", "options": ["50 cm² inclusive", "50 m²", "5 cm²"], "correct": 0, "explanation": "SI 1-3 excluye las penetraciones cuya sección no excede de 50 cm²."}, {"id": "cte-q17", "block": "reaccion", "page": 17, "q": "El revestimiento de suelo de un pasillo protegido será, según tabla 4.1…", "options": ["E_FL", "C_FL-s1", "B-s3,d0"], "correct": 1, "explanation": "C_FL-s1 corresponde a suelos de pasillos y escaleras protegidos; B-s1,d0 a sus paredes y techos."}, {"id": "cte-q18", "block": "reaccion", "page": 17, "q": "El porcentaje que activa las condiciones de revestimientos de la tabla 4.1 es…", "options": ["Más del 50%", "Cualquier porcentaje en todos los casos", "Más del 5% de la superficie del conjunto correspondiente"], "correct": 2, "explanation": "Se comprueba por separado el conjunto de paredes, el de techos o el de suelos del recinto."}, {"id": "cte-q19", "block": "exterior", "page": 19, "q": "La separación mínima de puntos no EI 60 en fachadas a 90° es…", "options": ["2 m", "3 m", "0,50 m"], "correct": 0, "explanation": "La tabla SI 2-1 relaciona ángulo y distancia: a 90°, 2 m; a 0°, 3 m; a 180°, 0,50 m."}, {"id": "cte-q20", "block": "exterior", "page": 20, "q": "La franja base para limitar propagación vertical por fachada es…", "options": ["EI 120 y 0,50 m", "EI 60 y 1 m de altura", "REI 30 y 2 m"], "correct": 1, "explanation": "Su altura puede reducirse en la dimensión de un saliente apto para impedir el paso de las llamas."}, {"id": "cte-q21", "block": "exterior", "page": 20, "q": "En una cámara ventilada de fachada de más de 28 m, el aislamiento será al menos…", "options": ["C-s3,d0", "D-s3,d0", "A2-s3,d0"], "correct": 2, "explanation": "No confundas la clasificación del aislamiento de la cámara con la del sistema constructivo de fachada."}, {"id": "cte-q22", "block": "ocupacion", "page": 23, "q": "La densidad para plantas de vivienda es…", "options": ["20 m²/persona", "10 m²/persona", "2 m²/persona"], "correct": 0, "explanation": "La tabla usa superficie útil por persona. Las zonas de alojamiento residencial público también tienen 20 m²/persona."}, {"id": "cte-q23", "block": "ocupacion", "page": 23, "q": "Un aula ordinaria de 90 m² útiles, con la densidad de tabla y sin otras condiciones, tiene…", "options": ["135 ocupantes", "60 ocupantes", "45 ocupantes"], "correct": 1, "explanation": "Se divide la superficie útil entre 1,5 m²/persona."}, {"id": "cte-q24", "block": "ocupacion", "page": 23, "q": "0,25 m²/persona para espectadores de pie equivale a…", "options": ["0,25 personas/m²", "2 personas/m²", "4 personas/m²"], "correct": 2, "explanation": "La densidad está expresada en superficie por persona; para invertirla, 1 / 0,25 = 4."}, {"id": "cte-q25", "block": "salidas", "page": 25, "q": "Con una única salida, el recorrido máximo específico en Aparcamiento es…", "options": ["35 m", "25 m en todos los casos", "75 m"], "correct": 0, "explanation": "La regla general de una salida es 25 m; Aparcamiento tiene 35 m. Hay además el supuesto de salida directa a exterior seguro y ≤ 25 personas."}, {"id": "cte-q26", "block": "salidas", "page": 25, "q": "Con varias salidas, el recorrido máximo en zonas donde se prevé que duerman ocupantes es…", "options": ["50 m sin excepción", "35 m", "15 m"], "correct": 1, "explanation": "Los 15 m son el tramo hasta alternativas en plantas de hospitalización/tratamiento intensivo, no el recorrido total de todas las zonas donde se duerme."}, {"id": "cte-q27", "block": "salidas", "page": 25, "q": "La extinción automática permite aumentar las longitudes de la tabla 3.1 en…", "options": ["50%", "100%", "25%"], "correct": 2, "explanation": "La nota 1 se refiere a sectores protegidos con instalación automática de extinción. No duplica automáticamente las longitudes."}, {"id": "cte-q28", "block": "anchuras", "page": 26, "q": "Para P = 240 asignadas a una puerta, P/200 da…", "options": ["1,20 m", "0,80 m", "1,50 m"], "correct": 0, "explanation": "El mínimo de 0,80 m no sustituye a la anchura que resulte del número de personas."}, {"id": "cte-q29", "block": "anchuras", "page": 26, "q": "La fórmula de una escalera no protegida para evacuación ascendente es…", "options": ["A ≥ P/200", "A ≥ P/(160 − 10h)", "A ≥ P/600"], "correct": 1, "explanation": "El término de altura h reduce la capacidad de la escalera ascendente."}, {"id": "cte-q30", "block": "anchuras", "page": 25, "q": "Si deben existir varias escaleras protegidas, el cálculo…", "options": ["Exige cerrar todas excepto una", "Ignora la asignación de ocupantes", "No exige inutilizar completamente una de ellas"], "correct": 2, "explanation": "La excepción al bloqueo total se aplica a protegidas, especialmente protegidas y compartimentadas como sector; no elimina el resto de hipótesis de asignación."}, {"id": "cte-q31", "block": "escaleras", "page": 28, "q": "Una escalera descendente de vivienda con h = 18 m exige como mínimo…", "options": ["Protegida", "No protegida", "Ninguna condición por altura"], "correct": 0, "explanation": "La no protegida llega hasta 14 m; la protegida se admite hasta 28 m."}, {"id": "cte-q32", "block": "escaleras", "page": 28, "q": "En Aparcamiento, las escaleras de evacuación deben ser…", "options": ["No protegidas si h < 14 m", "Especialmente protegidas", "Protegidas sin vestíbulo en todo caso"], "correct": 1, "explanation": "La tabla no admite las dos categorías inferiores en Aparcamiento, tanto para evacuación descendente como ascendente."}, {"id": "cte-q33", "block": "escaleras", "page": 45, "q": "La opción de ventilación natural de una escalera protegida exige, por planta…", "options": ["0,20 m² en total", "5 m² por cada ocupante", "Al menos 1 m² útil de ventilación"], "correct": 2, "explanation": "Es una de las tres opciones de protección frente al humo; no es la definición de escalera abierta al exterior."}, {"id": "cte-q34", "block": "puertas", "page": 29, "q": "Una puerta de salida de un recinto con 60 ocupantes debe abrir…", "options": ["En el sentido de evacuación", "En cualquier sentido por no llegar a 100", "Solo hacia dentro"], "correct": 0, "explanation": "El criterio de más de 50 ocupantes del recinto es independiente del de 100 o 200 personas por puerta."}, {"id": "cte-q35", "block": "puertas", "page": 29, "q": "Para usuarios no familiarizados, la barra horizontal de apertura se asocia a…", "options": ["UNE-EN 179", "UNE-EN 1125", "UNE 23034"], "correct": 1, "explanation": "UNE-EN 179 corresponde a manilla o pulsador para usuarios familiarizados. La señalización se regula en UNE 23034."}, {"id": "cte-q36", "block": "puertas", "page": 30, "q": "La señal «Sin salida» se coloca…", "options": ["Sobre la hoja a la altura de la manilla", "Solo en el techo del recinto", "Junto a la puerta, nunca sobre sus hojas"], "correct": 2, "explanation": "Debe ser fácilmente visible sin colocarse sobre las hojas de la puerta."}, {"id": "cte-q37", "block": "humo-refugio", "page": 31, "q": "Para 220 ocupantes, cuando procede refugio en uso distinto de vivienda, la dotación es…", "options": ["3 plazas de silla y 7 de otra movilidad reducida", "2 plazas de silla y 6 de otra movilidad reducida", "3 plazas de silla y ninguna otra"], "correct": 0, "explanation": "Se aplica una plaza por cada 100 y por cada 33 ocupantes o fracción. La excepción de la segunda dotación corresponde a vivienda."}, {"id": "cte-q38", "block": "humo-refugio", "page": 30, "q": "En Comercial o Pública concurrencia, SI 3 exige control de humo por ocupación cuando esta…", "options": ["Excede de 100 personas", "Excede de 1.000 personas", "Alcanza exactamente 500 personas"], "correct": 1, "explanation": "El umbral de 500 se refiere a los atrios en los términos del apartado, no a estos dos usos en general."}, {"id": "cte-q39", "block": "humo-refugio", "page": 30, "q": "La solución mecánica de aparcamiento de SI 3 indica extracción y aportación máxima de…", "options": ["120 y 150 l/(plaza·s)", "150 y 120 m³/(plaza·s)", "150 y 120 l/(plaza·s), respectivamente"], "correct": 2, "explanation": "No intercambies los valores ni cambies litros por metros cúbicos. Se requiere activación automática por detección."}, {"id": "cte-q40", "block": "instalaciones", "page": 32, "q": "La referencia general de eficacia y recorrido hasta extintor es…", "options": ["21A-113B y máximo 15 m", "13A-89B y máximo 25 m", "21A-113B y máximo 50 m"], "correct": 0, "explanation": "Se mide recorrido desde todo origen de evacuación, en cada planta."}, {"id": "cte-q41", "block": "instalaciones", "page": 33, "q": "En una cocina de uso Hospitalario, la extinción automática se exige si la potencia…", "options": ["Alcanza 50 kW exclusivamente", "Excede de 20 kW", "Excede de 80 kW"], "correct": 1, "explanation": "El umbral para Hospitalario y Residencial Público es mayor que 20 kW; para los demás usos, mayor que 50 kW."}, {"id": "cte-q42", "block": "instalaciones", "page": 35, "q": "En riesgo especial alto, el recorrido real hasta algún extintor no será mayor que…", "options": ["15 m", "25 m", "10 m"], "correct": 2, "explanation": "Se cuenta también el extintor exterior próximo a la puerta. Los 25 m de SI 1 se refieren a evacuación hasta alguna salida del local."}, {"id": "cte-q43", "block": "dotacion-usos", "page": 33, "q": "La columna seca se exige en Hospitalario si la altura de evacuación…", "options": ["Excede de 15 m", "Excede de 24 m", "Excede de 50 m"], "correct": 0, "explanation": "El umbral hospitalario es distinto al de vivienda y varios de los demás usos."}, {"id": "cte-q44", "block": "dotacion-usos", "page": 34, "q": "En Pública concurrencia, el sistema de alarma con megafonía se exige si…", "options": ["La superficie supera 500 m² en todos los casos", "La ocupación excede de 500 personas", "La altura alcanza 28 m"], "correct": 1, "explanation": "No confundas el umbral de ocupación de alarma con el de superficie para BIE."}, {"id": "cte-q45", "block": "dotacion-usos", "page": 35, "q": "Un aparcamiento robotizado debe disponer en todo caso de…", "options": ["Solo BIE de 25 mm", "Solo detectores si supera 2.000 m²", "Pulsadores de alarma y extinción automática"], "correct": 2, "explanation": "La tabla impone estos dos sistemas sin umbral de superficie para el robotizado."}, {"id": "cte-q46", "block": "aproximacion", "page": 36, "q": "El vial de aproximación debe tener anchura y gálibo mínimos de…", "options": ["3,5 y 4,5 m", "5 y 3,5 m", "4,5 y 3,5 m"], "correct": 0, "explanation": "La anchura de 5 m pertenece al espacio de maniobra, no al vial."}, {"id": "cte-q47", "block": "aproximacion", "page": 36, "q": "La capacidad portante del vial de aproximación es…", "options": ["100 kN/m²", "20 kN/m²", "20 kN sobre Ø 20 cm"], "correct": 1, "explanation": "Es una carga por superficie. El requisito de punzonamiento del espacio de maniobra usa otra magnitud."}, {"id": "cte-q48", "block": "aproximacion", "page": 36, "q": "En curva, los radios mínimos interior y exterior son…", "options": ["3,50 y 4,50 m", "7,20 y 20 m", "5,30 y 12,50 m"], "correct": 2, "explanation": "La anchura libre de circulación correspondiente es 7,20 m."}, {"id": "cte-q49", "block": "maniobra", "page": 36, "q": "Para altura de evacuación de 18 m, la separación máxima a fachada es…", "options": ["18 m", "23 m", "10 m"], "correct": 0, "explanation": "18 m pertenece al tramo mayor de 15 y hasta 20 m de altura de evacuación."}, {"id": "cte-q50", "block": "maniobra", "page": 36, "q": "El espacio de maniobra se exige por el apartado 1.2 con altura descendente…", "options": ["Mayor que 28 m", "Mayor que 9 m", "Igual o mayor que 3,5 m"], "correct": 1, "explanation": "No confundas la altura que activa el requisito con los tramos que fijan la separación a fachada."}, {"id": "cte-q51", "block": "maniobra", "page": 37, "q": "La distancia del equipo de bombeo a cada conexión de columna seca debe ser…", "options": ["Hasta 30 m inclusive", "Menor que 23 m", "Menor que 18 m"], "correct": 2, "explanation": "Además, el punto de conexión debe ser visible desde el camión de bombeo. Los 30 m se refieren al acceso al edificio."}, {"id": "cte-q52", "block": "fachada-forestal", "page": 37, "q": "Las dimensiones mínimas horizontal y vertical del hueco de acceso son…", "options": ["0,80 × 1,20 m", "1,20 × 0,80 m", "1,00 × 1,00 m"], "correct": 0, "explanation": "Además, alféizar ≤ 1,20 m y separación entre ejes consecutivos ≤ 25 m."}, {"id": "cte-q53", "block": "fachada-forestal", "page": 37, "q": "El camino perimetral de 5 m en entorno forestal…", "options": ["Debe sumarse siempre a la franja para llegar a 30 m", "Puede estar incluido en la franja de 25 m", "Sustituye por sí solo a la franja"], "correct": 1, "explanation": "La franja y el camino son requisitos relacionados; el texto permite incluir el camino en la franja."}, {"id": "cte-q54", "block": "fachada-forestal", "page": 37, "q": "Si no hay dos vías de acceso alternativas en la zona forestal, el acceso único acaba en…", "options": ["Fondo de saco de diámetro 12,50 m", "Un pasillo de 0,80 m", "Fondo de saco circular de radio 12,50 m"], "correct": 2, "explanation": "12,50 m es el radio, no el diámetro. También se mantienen las condiciones de espacio sin obstáculos."}, {"id": "cte-q55", "block": "estructura", "page": 39, "q": "La estructura de un aparcamiento situado bajo otro uso exige como regla…", "options": ["R 120", "R 30", "R 60"], "correct": 0, "explanation": "Si el aparcamiento es robotizado bajo otro uso, R 180. El exclusivo o situado sobre otro uso tiene R 90."}, {"id": "cte-q56", "block": "estructura", "page": 39, "q": "En Administrativo sobre rasante, con altura de evacuación de 20 m, la tabla exige…", "options": ["R 60", "R 90", "R 180"], "correct": 1, "explanation": "El tramo es mayor de 15 y hasta 28 m. No uses la fila de Comercial/Hospitalario."}, {"id": "cte-q57", "block": "estructura", "page": 39, "q": "SI 6 considera la capacidad portante de la estructura tras el incendio…", "options": ["Sí, para cualquier daño residual", "Solo si el incendio duró menos de 30 minutos", "No, queda fuera de su evaluación"], "correct": 2, "explanation": "SI 6 evalúa la resistencia durante el incendio; no acredita la capacidad portante residual."}, {"id": "cte-q58", "block": "anejos", "page": 53, "q": "En la curva θg = 20 + 345 log₁₀(8t + 1), t se mide en…", "options": ["Minutos", "Segundos", "Horas"], "correct": 0, "explanation": "La temperatura se expresa en grados Celsius y t es el tiempo desde el inicio en minutos."}, {"id": "cte-q59", "block": "anejos", "page": 73, "q": "El método de la sección reducida corresponde al anejo de…", "options": ["Acero, Anejo D", "Madera, Anejo E", "Fábrica, Anejo F"], "correct": 1, "explanation": "La sección eficaz se obtiene eliminando la profundidad de carbonización eficaz en las caras expuestas."}, {"id": "cte-q60", "block": "anejos", "page": 85, "q": "Para tablas de resistencia de muros de ladrillo y bloques de hormigón consultarías…", "options": ["Anejo B", "Anejo D", "Anejo F"], "correct": 2, "explanation": "El Anejo F trata de elementos de fábrica; B, del tiempo equivalente; D, del acero."}];
const sourceLink=(p,label)=>`<a href="cte-si-assets/CTE-DBSI.pdf#page=${p}" target="_blank" rel="noopener">${label||'p. '+p} ↗</a>`;
const blocks=[...document.querySelectorAll('#study section')];
const state={get(k,f){try{return JSON.parse(localStorage.getItem('cte-si-'+k))??f}catch{return f}},set(k,v){try{localStorage.setItem('cte-si-'+k,JSON.stringify(v))}catch{}}};
let done=new Set(state.get('blocks-v1',[]));
function progress(){const n=blocks.filter(b=>done.has(b.id)).length;document.querySelector('#progressbar').style.width=(n/blocks.length*100)+'%';const p=document.querySelector('.progress');p.setAttribute('aria-valuemax',blocks.length);p.setAttribute('aria-valuenow',n);document.querySelector('#progresslabel').textContent=`${n} de ${blocks.length} bloques repasados`;document.querySelector('#mobileprogress').textContent=`· ${n}/${blocks.length}`;state.set('blocks-v1',[...done])}
document.querySelector('#index').innerHTML=blocks.map((b,i)=>`<a href="#${b.id}" data-block="${b.id}"><span>${String(i+1).padStart(2,'0')}</span>${b.dataset.title}</a>`).join('');document.querySelector('#mobilelinks').innerHTML=document.querySelector('#index').innerHTML;
blocks.forEach(b=>{const label=document.createElement('label');label.className='done';const c=document.createElement('input');c.type='checkbox';c.checked=done.has(b.id);c.addEventListener('change',()=>{c.checked?done.add(b.id):done.delete(b.id);progress()});label.append(c,document.createTextNode('Puedo explicar este bloque sin mirar'));b.append(label)});progress();
const tabs=[...document.querySelectorAll('[data-view]')];let currentView='study';
function showView(v,scroll=true){currentView=v;document.querySelectorAll('.view').forEach(e=>e.hidden=e.id!==v);tabs.forEach(t=>{const active=t.dataset.view===v;t.setAttribute('aria-selected',active);t.tabIndex=active?0:-1});document.querySelector('#studytools').hidden=v!=='study';document.querySelector('.mobileindex').hidden=v!=='study';if(scroll)document.querySelector('main').scrollIntoView({behavior:'auto',block:'start'})}
tabs.forEach((t,i)=>{t.addEventListener('click',()=>showView(t.dataset.view));t.addEventListener('keydown',e=>{let j;if(e.key==='ArrowRight')j=(i+1)%tabs.length;else if(e.key==='ArrowLeft')j=(i-1+tabs.length)%tabs.length;else if(e.key==='Home')j=0;else if(e.key==='End')j=tabs.length-1;if(j!==undefined){e.preventDefault();tabs[j].focus();showView(tabs[j].dataset.view)}})});
function normalize(s){return s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'')}
function searchBlocks(){const q=normalize(document.querySelector('#search').value.trim());let n=0;blocks.forEach(b=>{b.hidden=q&&!normalize(b.textContent).includes(q);if(!b.hidden)n++});document.querySelector('#noresults').hidden=n>0;document.querySelector('#resultcount').textContent=q?`${n} ${n===1?'bloque':'bloques'}`:''}
document.querySelector('#search').addEventListener('input',searchBlocks);document.querySelector('#essentials').checked=state.get('essentials',false);document.querySelector('#study').classList.toggle('onlyessential',document.querySelector('#essentials').checked);document.querySelector('#essentials').addEventListener('change',e=>{document.querySelector('#study').classList.toggle('onlyessential',e.target.checked);state.set('essentials',e.target.checked)});
document.addEventListener('click',e=>{const a=e.target.closest('a[href^="#"]');if(a&&document.querySelector(a.getAttribute('href'))?.matches('#study section')){showView('study',false);document.querySelector('#search').value='';searchBlocks();document.querySelector('.mobileindex').open=false;document.querySelector(a.getAttribute('href')).scrollIntoView();}});
const observer=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting)document.querySelectorAll('#index a').forEach(a=>a.classList.toggle('active',a.dataset.block===e.target.id))})},{rootMargin:'-110px 0px -65% 0px'});blocks.forEach(b=>observer.observe(b));
document.querySelector('#print').addEventListener('click',()=>window.print());
let printSnapshot;
window.addEventListener('beforeprint',()=>{const ds=[...document.querySelectorAll('#study details')];printSnapshot={essential:document.querySelector('#study').classList.contains('onlyessential'),details:ds.map(d=>[d,d.open])};document.querySelector('#study').classList.remove('onlyessential');ds.forEach(d=>d.open=true)});
window.addEventListener('afterprint',()=>{if(!printSnapshot)return;document.querySelector('#study').classList.toggle('onlyessential',printSnapshot.essential);printSnapshot.details.forEach(([d,open])=>d.open=open);printSnapshot=null});
const topicName=id=>blocks.find(b=>b.id===id)?.dataset.title||id;
const optionTopics=blocks.map(b=>`<option value="${b.id}">${b.dataset.title}</option>`).join('');document.querySelector('#cardtopic').insertAdjacentHTML('beforeend',optionTopics);document.querySelector('#quiztopic').insertAdjacentHTML('beforeend',optionTopics);
const sourceRanges={"marco": [2, 7], "terminos": [42, 49], "sectores": [10, 12], "resistencia-sector": [13, 13], "riesgo": [14, 16], "reaccion": [16, 18], "exterior": [19, 21], "ocupacion": [22, 24], "salidas": [24, 25], "anchuras": [25, 28], "escaleras": [28, 28, 44, 45], "puertas": [29, 30], "humo-refugio": [30, 31, 52, 52], "instalaciones": [32, 35], "dotacion-usos": [33, 35, 42, 42], "aproximacion": [36, 36], "maniobra": [36, 37], "fachada-forestal": [37, 37], "estructura": [38, 41], "anejos": [53, 53, 57, 57, 69, 69, 73, 73, 85, 86]};
blocks.forEach(b=>{const vals=sourceRanges[b.id];const pages=new Set();for(let i=0;i<vals.length;i+=2){for(let p=vals[i];p<=vals[i+1];p++)pages.add(p)}const d=document.createElement('details');d.className='extra sourcelinks';d.innerHTML='<summary>Consultar las páginas de este bloque</summary><div class="sourcegrid">'+[...pages].sort((a,b)=>a-b).map(p=>sourceLink(p)).join('')+'</div>';b.insertBefore(d,b.querySelector('.done'))});
document.querySelector('#quickgrid').innerHTML=blocks.map((b,i)=>`<div class="quickcard"><div class="overline">${String(i+1).padStart(2,'0')}</div><h3>${b.dataset.title}</h3><p>${b.querySelector('.essential').innerHTML.replace(/<div class="overline">.*?<\/div>/,'')}</p><a href="#${b.id}">Revisar el bloque →</a></div>`).join('');
const storyNodes=[...document.querySelectorAll('#study .story')];document.querySelector('#stories').innerHTML=storyNodes.map(s=>`<div class="story">${s.innerHTML}<a class="note" href="#${s.closest('section').id}">Ver el dato en su contexto →</a></div>`).join('');
function renderPegs(){const q=normalize(document.querySelector('#pegsearch').value.trim());const matches=pegs.map((label,n)=>({label,n})).filter(p=>!q||normalize(p.n+' '+p.label).includes(q));document.querySelector('#peglist').innerHTML=matches.length?matches.map(p=>`<div class="peg"><b>${p.n}</b>${p.label}</div>`).join(''):'<p class="note">No hay casillas con ese término.</p>'}document.querySelector('#pegsearch').addEventListener('input',renderPegs);renderPegs();
let cardState=state.get('cards-v1',{});let deck=[],position=0,revealed=false;
function cardPool(){const type=document.querySelector('#deck').value;const topic=document.querySelector('#cardtopic').value;return flashcards.filter(c=>{const s=cardState[c.id];return(topic==='all'||c.block===topic)&&(type==='all'||(type==='repeat'&&s?.repeat)||(type==='due'&&(!s?.due||s.due<=Date.now())))})}
function renderCard(status=''){revealed=false;const c=deck[position];document.querySelector('#flasha').hidden=true;document.querySelector('#again').disabled=true;document.querySelector('#remember').disabled=true;document.querySelector('#flashstatus').textContent=status;const nDue=flashcards.filter(c=>!cardState[c.id]?.due||cardState[c.id].due<=Date.now()).length;document.querySelector('#flashcount').textContent=c?`Tarjeta ${position+1} de ${deck.length} · ${nDue} pendientes hoy en total`:`Mazo vacío · ${nDue} pendientes hoy en total`;document.querySelector('#flashtag').textContent=c?topicName(c.block)+' · p. '+c.page:'Sin tarjetas pendientes';document.querySelector('#flashq').textContent=c?c.q:'Has completado este mazo. Puedes practicar todas las tarjetas o cambiar de bloque.';document.querySelector('#reveal').disabled=!c;document.querySelector('#prev').disabled=!c;document.querySelector('#next').disabled=!c;document.querySelector('#flasha').innerHTML=c?`<p>${c.a}</p><a href="#${c.block}">Revisar el bloque →</a> ${sourceLink(c.page,'Ver fuente')}`:'';}
function rebuildDeck(){deck=cardPool();position=0;renderCard()}
document.querySelector('#deck').onchange=rebuildDeck;document.querySelector('#cardtopic').onchange=rebuildDeck;document.querySelector('#shuffle').onclick=()=>{deck=cardPool();for(let i=deck.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[deck[i],deck[j]]=[deck[j],deck[i]]}position=0;renderCard()};
function revealCard(){if(!deck.length)return;revealed=true;document.querySelector('#flasha').hidden=false;document.querySelector('#again').disabled=false;document.querySelector('#remember').disabled=false;document.querySelector('#reveal').hidden=true;document.querySelector('#flasha').focus()}
const originalRenderCard=renderCard;renderCard=function(status=''){document.querySelector('#reveal').hidden=false;originalRenderCard(status)};
document.querySelector('#reveal').onclick=revealCard;
function moveCard(delta){if(!deck.length)return;position=(position+delta+deck.length)%deck.length;renderCard()}document.querySelector('#prev').onclick=()=>moveCard(-1);document.querySelector('#next').onclick=()=>moveCard(1);
function gradeCard(remember){if(!revealed||!deck.length)return;const c=deck[position];const previous=cardState[c.id]||{};let label;if(remember){const level=Math.min((previous.level||0)+1,4);const days=[1,3,7,14][level-1];const due=Date.now()+days*86400000;cardState[c.id]={level,due,repeat:false};label=`Guardada. Próximo repaso: ${new Intl.DateTimeFormat('es-ES',{timeZone:'Europe/Madrid',day:'numeric',month:'long'}).format(due)} (en ${days} ${days===1?'día':'días'}).`}else{cardState[c.id]={level:0,due:Date.now(),repeat:true};label='Guardada para repetir hoy. También está en el mazo «Para repetir».'}state.set('cards-v1',cardState);const oldPos=position;const nextPool=cardPool();const ids=new Set(nextPool.map(x=>x.id));deck=deck.filter(x=>ids.has(x.id));const idx=deck.findIndex(x=>x.id===c.id);position=idx>=0?(idx+1)%deck.length:Math.min(oldPos,Math.max(deck.length-1,0));renderCard(label)}document.querySelector('#again').onclick=()=>gradeCard(false);document.querySelector('#remember').onclick=()=>gradeCard(true);rebuildDeck();
document.addEventListener('keydown',e=>{if(currentView!=='flash'||e.target.matches('input,select,textarea,button,a'))return;if(e.key===' '){e.preventDefault();if(!revealed)revealCard()}if(e.key==='ArrowRight'){e.preventDefault();moveCard(1)}if(e.key==='ArrowLeft'){e.preventDefault();moveCard(-1)}});
let quizAnswers={};
const quizEscape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function quizPool(){const topic=document.querySelector('#quiztopic').value;return quizdata.map((q,i)=>({q,i})).filter(({q})=>(topic==='all'||q.block===topic))}
function updateScore(){const visible=quizPool();const answered=visible.filter(x=>Object.hasOwn(quizAnswers,x.i));const correct=answered.filter(x=>quizAnswers[x.i]===x.q.correct);document.querySelector('#score').textContent=`${correct.length} ${correct.length===1?'acierto':'aciertos'} · ${answered.length}/${visible.length} respondidas`}
function renderQuiz(){const visible=quizPool();document.querySelector('#quizlist').innerHTML=visible.length?visible.map(({q,i})=>`<article class="quizitem" data-question="${i}"${q.id?` id="quiz-${quizEscape(q.id)}"`:''}><div class="quizmeta"><div class="overline">${q.origin==='academia'?quizEscape(q.sourceLabel)+' · '+q.sourceNumber:'Cuaderno · '+(i+1)} · ${quizEscape(topicName(q.block))}</div>${q.review?'<span class="quizbadge">Con aclaración en la corrección</span>':''}</div><h3>${quizEscape(q.q)}</h3><div class="options">${q.options.map((o,j)=>`<button data-answer="${j}"><span aria-hidden="true">${String.fromCharCode(65+j)} · </span>${quizEscape(o)}</button>`).join('')}</div><div class="feedback" hidden role="status"></div></article>`).join(''):'<p class="empty" role="status">Este test no contiene preguntas de ese bloque. Cambia el test o selecciona «Todo el tema».</p>';Object.entries(quizAnswers).forEach(([i,answer])=>displayAnswer(Number(i),answer));updateScore()}
function displayAnswer(i,answer){const row=document.querySelector(`[data-question="${i}"]`);if(!row)return;const q=quizdata[i];const correct=answer===q.correct;row.querySelectorAll('[data-answer]').forEach(b=>{const n=Number(b.dataset.answer);b.disabled=true;b.classList.toggle('correct',n===q.correct);b.classList.toggle('wrong',n===answer&&!correct);b.setAttribute('aria-label',q.options[n]+(n===q.correct?' · Respuesta correcta':n===answer?' · Tu respuesta incorrecta':''))});const feedback=row.querySelector('.feedback');feedback.hidden=false;feedback.classList.toggle('error',!correct);const pageLinks=[...new Set([q.page,...(q.extraPages||[])])].filter(p=>Number.isInteger(p)&&p>=1&&p<=92).map(p=>sourceLink(p)).join('');const review=q.review?`<details class="quizreview"><summary>${quizEscape(q.review.title)}</summary><p>${quizEscape(q.review.text)}</p>${q.review.links?.length?`<ul>${q.review.links.map(link=>`<li><a href="${quizEscape(link.url)}" target="_blank" rel="noopener noreferrer">${quizEscape(link.title)} ↗</a></li>`).join('')}</ul>`:''}</details>`:'';feedback.innerHTML=`<p><b>${correct?'Correcto.':'Revisa: '+quizEscape(q.options[q.correct])+'.'}</b> ${quizEscape(q.explanation)}</p>${q.contrast?`<p><b>Para distinguirlo.</b> ${quizEscape(q.contrast)}</p>`:''}${review}<div class="quizlinks"><a href="#${q.block}">${q.origin==='academia'?'Revisar bloque relacionado':'Volver al bloque'} →</a>${pageLinks?'<span>Consultar PDF:</span>'+pageLinks:'<span>Clave procedente del test compartido.</span>'}</div>`}
document.querySelector('#quizlist').addEventListener('click',e=>{const button=e.target.closest('[data-answer]');if(!button)return;const i=Number(button.closest('[data-question]').dataset.question);if(Object.hasOwn(quizAnswers,i))return;quizAnswers[i]=Number(button.dataset.answer);displayAnswer(i,quizAnswers[i]);updateScore()});document.querySelector('#quiztopic').onchange=renderQuiz;document.querySelector('#resetquiz').onclick=()=>{quizPool().forEach(({i})=>delete quizAnswers[i]);renderQuiz()};renderQuiz();
function openHash(){const id=location.hash.slice(1);if(['quick','flash','quiz','images','memory'].includes(id))showView(id,false);else if(blocks.some(b=>b.id===id)){showView('study',false);document.querySelector('#search').value='';searchBlocks();document.querySelector('.mobileindex').open=false;requestAnimationFrame(()=>document.getElementById(id).scrollIntoView())}}window.addEventListener('hashchange',openHash);openHash();
